   "limit": "int (optional) \u2014 max items"
  }
 },
 {
  "name": "news_search",
  "description": "Search recent news headlines across outlets (Google News + Bing News).",
  "args": {
   "query": "str \u2014 search words",
   "days": "int (optional) \u2014 how many days back",
   "limit": "int (optional) \u2014 max items"
  }
 },
